"""Page-one HiCache CPU copy-queue cost, with unchanged FP8/BF16 bytes."""
_HEADER = '#pragma once\n\n#include "hicache.cuh"\n#include "relayout.cuh"\n#include <dlfcn.h>\n#include <limits>\n#include <vector>\n\nnamespace hicache_coalesced_lab {\nusing namespace sglang;\n\n#if !defined(USE_ROCM) && defined(CUDA_VERSION) && CUDA_VERSION >= 12080\n#if CUDA_VERSION >= 13000\nusing CudaMemcpyBatchPtr = const void*;\nusing CudaMemcpyBatchAsyncFn = cudaError_t (*)(\n    CudaMemcpyBatchPtr*,\n    CudaMemcpyBatchPtr*,\n    const size_t*,\n    size_t,\n    cudaMemcpyAttributes*,\n    size_t*,\n    size_t,\n    cudaStream_t);\n#else\nusing CudaMemcpyBatchPtr = void*;\nusing CudaMemcpyBatchAsyncFn = cudaError_t (*)(\n    CudaMemcpyBatchPtr*,\n    CudaMemcpyBatchPtr*,\n    size_t*,\n    size_t,\n    cudaMemcpyAttributes*,\n    size_t*,\n    size_t,\n    size_t*,\n    cudaStream_t);\n#endif\n\ninline auto get_cuda_memcpy_batch_async() -> CudaMemcpyBatchAsyncFn {\n  static CudaMemcpyBatchAsyncFn cuda_memcpy_batch_async = []() {\n    void* symbol = dlsym(RTLD_DEFAULT, "cudaMemcpyBatchAsync");\n    return reinterpret_cast<CudaMemcpyBatchAsyncFn>(symbol);\n  }();\n  return cuda_memcpy_batch_async;\n}\n\ninline auto call_cuda_memcpy_batch_async(\n    CudaMemcpyBatchAsyncFn copy_fn,\n    CudaMemcpyBatchPtr* dsts,\n    CudaMemcpyBatchPtr* srcs,\n    size_t* sizes,\n    size_t count,\n    cudaMemcpyAttributes* attrs,\n    size_t* attrs_idxs,\n    size_t num_attrs,\n    cudaStream_t stream) -> cudaError_t {\n#if CUDA_VERSION >= 13000\n  return copy_fn(dsts, srcs, sizes, count, attrs, attrs_idxs, num_attrs, stream);\n#else\n  size_t fail_idx = std::numeric_limits<size_t>::max();\n  return copy_fn(dsts, srcs, sizes, count, attrs, attrs_idxs, num_attrs, &fail_idx, stream);\n#endif\n}\n#endif\n\n#ifndef USE_ROCM\ninline size_t hicache_registered_bytes_remaining(const void* ptr) {\n  using QueryFn = CUresult (*)(unsigned int, CUpointer_attribute*, void**, CUdeviceptr);\n  static const QueryFn query = []() {\n    void* symbol = nullptr;\n    cudaDriverEntryPointQueryResult status;\n    host::RuntimeDeviceCheck(cudaGetDriverEntryPointByVersion(\n        "cuPointerGetAttributes", &symbol, 11000, cudaEnableDefault, &status));\n    host::RuntimeCheck(status == cudaDriverEntryPointSuccess && symbol != nullptr, "CUDA pointer range query unavailable");\n    return reinterpret_cast<QueryFn>(symbol);\n  }();\n  CUdeviceptr base = 0;\n  size_t bytes = 0;\n  CUpointer_attribute attrs[] = {CU_POINTER_ATTRIBUTE_RANGE_START_ADDR, CU_POINTER_ATTRIBUTE_RANGE_SIZE};\n  void* values[] = {&base, &bytes};\n  const auto address = reinterpret_cast<CUdeviceptr>(ptr);\n  const auto result = query(2, attrs, values, address);\n  host::RuntimeCheck(result == CUDA_SUCCESS, "CUDA pointer range query failed: ", static_cast<int>(result));\n  // Unregistered host pointers have zero range attributes. They retain one\n  // copy per page; never merge across an unknown or separate registration.\n  return base <= address && address - base < bytes ? bytes - (address - base) : 0;\n}\n#endif\n\ninline void copy_page_first_pages_fallback(\n    const std::vector<tvm::ffi::TensorView>& src_ptrs,\n    std::vector<tvm::ffi::TensorView> dst_ptrs,\n    const int64_t* dst_indices_ptr,\n    int64_t num_pages,\n    int64_t page_size,\n    cudaStream_t stream) {\n  using namespace host;\n\n  RuntimeCheck(src_ptrs.size() == dst_ptrs.size(), "Source and destination tensors must have the same count");\n  for (const auto tensor_id : irange(src_ptrs.size())) {\n    RuntimeCheck(\n        src_ptrs[tensor_id].dtype() == dst_ptrs[tensor_id].dtype(),\n        "Source and destination tensors must have the same dtype");\n    const int64_t elem_size = host::dtype_bytes(src_ptrs[tensor_id].dtype());\n    const int64_t src_stride0 = src_ptrs[tensor_id].stride(0);\n    const int64_t dst_stride0 = dst_ptrs[tensor_id].stride(0);\n    const size_t src_page_bytes = static_cast<size_t>(page_size * src_stride0 * elem_size);\n    const size_t dst_page_bytes = static_cast<size_t>(page_size * dst_stride0 * elem_size);\n    RuntimeCheck(src_page_bytes == dst_page_bytes, "Source and destination page spans must match");\n    // Staging is contiguous in page order. Merge adjacent destination pages\n    // instead of submitting one host API call per page (page_size is 1 for\n    // Muse). Preserve order at gaps, descending indices and repeated slots.\n    for (int64_t page_offset = 0; page_offset < num_pages;) {\n      int64_t page_end = page_offset + 1;\n#ifndef USE_ROCM\n      while (page_end < num_pages &&\n             dst_indices_ptr[page_end * page_size] == dst_indices_ptr[(page_end - 1) * page_size] + page_size) {\n        ++page_end;\n      }\n#endif\n      const char* src_ptr = static_cast<const char*>(src_ptrs[tensor_id].data_ptr()) +\n                            static_cast<size_t>(page_offset * page_size * src_stride0 * elem_size);\n      char* dst_ptr = static_cast<char*>(dst_ptrs[tensor_id].data_ptr()) +\n                      static_cast<size_t>(dst_indices_ptr[page_offset * page_size] * dst_stride0 * elem_size);\n#ifndef USE_ROCM\n      if (page_end > page_offset + 1) {\n        const size_t span_bytes = hicache_registered_bytes_remaining(dst_ptr);\n        const int64_t span_pages = static_cast<int64_t>(std::max(size_t{1}, span_bytes / dst_page_bytes));\n        page_end = std::min(page_end, page_offset + span_pages);\n      }\n#endif\n      const size_t bytes = src_page_bytes * static_cast<size_t>(page_end - page_offset);\n      RuntimeDeviceCheck(cudaMemcpyAsync(dst_ptr, src_ptr, bytes, cudaMemcpyDeviceToHost, stream));\n      page_offset = page_end;\n    }\n  }\n}\n\ninline bool try_copy_page_first_pages_batch(\n    const std::vector<tvm::ffi::TensorView>& src_ptrs,\n    std::vector<tvm::ffi::TensorView> dst_ptrs,\n    const int64_t* dst_indices_ptr,\n    int64_t num_pages,\n    int64_t page_size,\n    int device_id,\n    cudaStream_t stream) {\n#if defined(USE_ROCM) || !defined(CUDA_VERSION) || (CUDA_VERSION < 12080)\n  return false;\n#else\n  host::RuntimeCheck(src_ptrs.size() == dst_ptrs.size(), "Source and destination tensors must have the same count");\n  constexpr size_t kLargeCopyThresholdBytes = 128 * 1024;\n  thread_local std::vector<CudaMemcpyBatchPtr> batch_srcs;\n  thread_local std::vector<CudaMemcpyBatchPtr> batch_dsts;\n  thread_local std::vector<size_t> batch_sizes;\n\n  int driver_version = 0;\n  cudaError_t driver_version_err = cudaDriverGetVersion(&driver_version);\n  if (driver_version_err != cudaSuccess || driver_version < 12080) {\n    return false;\n  }\n\n  auto copy_fn = get_cuda_memcpy_batch_async();\n  if (copy_fn == nullptr) {\n    return false;\n  }\n\n  const size_t num_copies = static_cast<size_t>(src_ptrs.size()) * static_cast<size_t>(num_pages);\n  batch_srcs.clear();\n  batch_dsts.clear();\n  batch_sizes.clear();\n  batch_srcs.reserve(num_copies);\n  batch_dsts.reserve(num_copies);\n  batch_sizes.reserve(num_copies);\n\n  size_t first_page_bytes = 0;\n  for (const auto tensor_id : host::irange(src_ptrs.size())) {\n    host::RuntimeCheck(\n        src_ptrs[tensor_id].dtype() == dst_ptrs[tensor_id].dtype(),\n        "Source and destination tensors must have the same dtype");\n    const int64_t elem_size = host::dtype_bytes(src_ptrs[tensor_id].dtype());\n    const int64_t src_stride0 = src_ptrs[tensor_id].stride(0);\n    const int64_t dst_stride0 = dst_ptrs[tensor_id].stride(0);\n    const size_t src_page_bytes = static_cast<size_t>(page_size * src_stride0 * elem_size);\n    const size_t dst_page_bytes = static_cast<size_t>(page_size * dst_stride0 * elem_size);\n    host::RuntimeCheck(src_page_bytes == dst_page_bytes, "Source and destination page spans must match");\n    if (tensor_id == 0) {\n      first_page_bytes = src_page_bytes;\n      if (first_page_bytes < kLargeCopyThresholdBytes) {\n        return false;\n      }\n    }\n    for (const auto page_offset : host::irange(num_pages)) {\n      char* src_ptr = static_cast<char*>(src_ptrs[tensor_id].data_ptr()) +\n                      static_cast<size_t>(page_offset * page_size * src_stride0 * elem_size);\n      char* dst_ptr = static_cast<char*>(dst_ptrs[tensor_id].data_ptr()) +\n                      static_cast<size_t>(dst_indices_ptr[page_offset * page_size] * dst_stride0 * elem_size);\n      batch_srcs.push_back(src_ptr);\n      batch_dsts.push_back(dst_ptr);\n      batch_sizes.push_back(src_page_bytes);\n    }\n  }\n  if (first_page_bytes < kLargeCopyThresholdBytes) {\n    return false;\n  }\n\n  std::vector<size_t> attrs_idxs(1, 0);\n  cudaMemcpyAttributes attrs{};\n  attrs.srcAccessOrder = cudaMemcpySrcAccessOrderStream;\n  attrs.srcLocHint.type = cudaMemLocationTypeDevice;\n  attrs.srcLocHint.id = device_id;\n  attrs.dstLocHint.type = cudaMemLocationTypeHost;\n  attrs.dstLocHint.id = 0;\n  attrs.flags = 0;\n\n  cudaError_t err = call_cuda_memcpy_batch_async(\n      copy_fn,\n      batch_dsts.data(),\n      batch_srcs.data(),\n      batch_sizes.data(),\n      num_copies,\n      &attrs,\n      attrs_idxs.data(),\n      1,\n      stream);\n  if (err == cudaErrorNotSupported || err == cudaErrorCallRequiresNewerDriver || err == cudaErrorInvalidValue) {\n    (void)cudaGetLastError();\n    return false;\n  }\n  host::RuntimeCheck(err == cudaSuccess, "cudaMemcpyBatchAsync failed. error=", cudaGetErrorString(err));\n  return true;\n#endif\n}\n\ntemplate <int64_t kElementSize, uint32_t kUnroll, uint32_t kBlockQuota, uint32_t kBlockSize>\nstruct HiCacheStagedWriteBackKernel {\n private:\n  template <bool kIsMLA>\n  static void run_staged_impl(\n      const tvm::ffi::TensorView k_cache_dst,\n      const tvm::ffi::TensorView v_cache_dst,\n      const tvm::ffi::TensorView dst_indices_cpu,\n      const tvm::ffi::TensorView staging_k,\n      const tvm::ffi::TensorView staging_v,\n      const tvm::ffi::TensorView page_indices_src,\n      const tvm::ffi::TensorView k_ptr_src,\n      const tvm::ffi::TensorView v_ptr_src,\n      const int64_t page_size) {\n    using namespace host;\n\n    auto T = SymbolicSize{"num_tokens"};\n    auto N = SymbolicSize{"num_layers"};\n    auto D = SymbolicSize{"element_dim"};\n    auto P = SymbolicSize{"num_pages"};\n    auto cache_dtype = SymbolicDType{};\n    auto indices_dtype = SymbolicDType{};\n    auto dst_indices_dtype = SymbolicDType{};\n    auto device_ = SymbolicDevice{};\n\n    TensorMatcher({T, N, D})  //\n        .with_dtype(cache_dtype)\n        .with_device<kDLGPU>(device_)\n        .verify(staging_k);\n    if constexpr (!kIsMLA) {\n      TensorMatcher({T, N, D})  //\n          .with_dtype(cache_dtype)\n          .with_device<kDLGPU>(device_)\n          .verify(staging_v);\n    }\n    TensorMatcher({-1, N, D})  //\n        .with_dtype(cache_dtype)\n        .with_device<kDLCPU, kDLGPUHost>()\n        .verify(k_cache_dst);\n    if constexpr (!kIsMLA) {\n      TensorMatcher({-1, N, D})  //\n          .with_dtype(cache_dtype)\n          .with_device<kDLCPU, kDLGPUHost>()\n          .verify(v_cache_dst);\n    }\n    TensorMatcher({N})  //\n        .with_dtype<uint64_t>()\n        .with_device<kDLGPU>(device_)\n        .verify(k_ptr_src);\n    if constexpr (!kIsMLA) {\n      TensorMatcher({N})  //\n          .with_dtype<uint64_t>()\n          .with_device<kDLGPU>(device_)\n          .verify(v_ptr_src);\n    }\n    TensorMatcher({P})  //\n        .with_dtype<int32_t, int64_t>(indices_dtype)\n        .with_device<kDLGPU>(device_)\n        .verify(page_indices_src);\n    TensorMatcher({T})  //\n        .with_dtype<int64_t>(dst_indices_dtype)\n        .with_device<kDLCPU, kDLGPUHost>()\n        .verify(dst_indices_cpu);\n\n    RuntimeCheck(page_size > 0, "HiCache staged relayout: page_size must be positive");\n    RuntimeCheck(T.unwrap() == P.unwrap() * page_size, "HiCache staged relayout: staging token count mismatch");\n    RuntimeCheck(\n        kElementSize == D.unwrap() * dtype_bytes(cache_dtype.unwrap()),\n        "HiCache staged relayout: element size mismatch");\n    RuntimeCheck(kElementSize % 16 == 0, "HiCache staged relayout: element size must be 16-byte aligned");\n\n    const auto params = HicacheRelayoutParams{\n        .k_cache_dst = staging_k.data_ptr(),\n        .v_cache_dst = kIsMLA ? nullptr : staging_v.data_ptr(),\n        .indices_src = page_indices_src.data_ptr(),\n        .k_ptr_src = k_ptr_src.data_ptr(),\n        .v_ptr_src = kIsMLA ? nullptr : v_ptr_src.data_ptr(),\n        .num_pages = static_cast<uint32_t>(P.unwrap()),\n        .num_layers = static_cast<uint32_t>(N.unwrap()),\n        .page_size = static_cast<uint32_t>(page_size),\n    };\n    const auto device = device_.unwrap();\n    const auto use_int32 = indices_dtype.unwrap().bits == 32;\n    launch_hicache_relayout_kernel<kElementSize, kIsMLA>(params, P.unwrap(), N.unwrap(), page_size, use_int32, device);\n\n    auto stream = LaunchKernel::resolve_device(device);\n    const int64_t* dst_indices_ptr = static_cast<const int64_t*>(dst_indices_cpu.data_ptr());\n    if constexpr (kIsMLA) {\n      if (!try_copy_page_first_pages_batch(\n              {staging_k}, {k_cache_dst}, dst_indices_ptr, P.unwrap(), page_size, device.device_id, stream)) {\n        copy_page_first_pages_fallback({staging_k}, {k_cache_dst}, dst_indices_ptr, P.unwrap(), page_size, stream);\n      }\n    } else {\n      if (!try_copy_page_first_pages_batch(\n              {staging_k, staging_v},\n              {k_cache_dst, v_cache_dst},\n              dst_indices_ptr,\n              P.unwrap(),\n              page_size,\n              device.device_id,\n              stream)) {\n        copy_page_first_pages_fallback(\n            {staging_k, staging_v}, {k_cache_dst, v_cache_dst}, dst_indices_ptr, P.unwrap(), page_size, stream);\n      }\n    }\n  }\n\n public:\n  static void run_all_lf_pf_staged(\n      const tvm::ffi::TensorView k_cache_dst,\n      const tvm::ffi::TensorView v_cache_dst,\n      const tvm::ffi::TensorView dst_indices_cpu,\n      const tvm::ffi::TensorView staging_k,\n      const tvm::ffi::TensorView staging_v,\n      const tvm::ffi::TensorView page_indices_src,\n      const tvm::ffi::TensorView k_ptr_src,\n      const tvm::ffi::TensorView v_ptr_src,\n      const int64_t page_size) {\n    run_staged_impl<false>(\n        k_cache_dst,\n        v_cache_dst,\n        dst_indices_cpu,\n        staging_k,\n        staging_v,\n        page_indices_src,\n        k_ptr_src,\n        v_ptr_src,\n        page_size);\n  }\n\n  static void run_all_mla_lf_pf_staged(\n      const tvm::ffi::TensorView cache_dst,\n      const tvm::ffi::TensorView dst_indices_cpu,\n      const tvm::ffi::TensorView staging,\n      const tvm::ffi::TensorView page_indices_src,\n      const tvm::ffi::TensorView ptr_src,\n      const int64_t page_size) {\n    run_staged_impl<true>(\n        cache_dst, cache_dst, dst_indices_cpu, staging, staging, page_indices_src, ptr_src, ptr_src, page_size);\n  }\n};\n\n}  // namespace sglang\n'


def lab(deadline, weights, state=None):
    import statistics
    import tempfile
    import time
    from pathlib import Path
    import torch
    import sglang.kernels.ops.kvcache.hicache as image
    from sglang.kernels.jit.utils import load_jit, make_cpp_args

    source_dir = Path(image.__file__).resolve().parents[2] / 'jit/csrc/kvcacheio'
    directory = tempfile.TemporaryDirectory(prefix='hicache-coalesced-lab-')
    header_path = Path(directory.name) / 'coalesced.cuh'
    header_path.write_text(_HEADER)
    compiled = {}
    lines = []
    for row_bytes, layers, dtype in [(128, 16, torch.float8_e4m3fn),
                                     (128, 46, torch.float8_e4m3fn),
                                     (320, 2, torch.bfloat16)]:
        if time.monotonic() + 15 > deadline:
            lines.append('BUDGET_STOP before compilation')
            break
        args = make_cpp_args(row_bytes, 4, 2, 1024)
        if row_bytes not in compiled:
            compiled[row_bytes] = load_jit('hicache_coalesced_lab_v1', *args,
                cuda_files=[str(header_path)], extra_include_paths=[str(source_dir)],
                cuda_wrappers=[('launch', f'&hicache_coalesced_lab::HiCacheStagedWriteBackKernel<{args}>::run_all_lf_pf_staged')])
        original = image._jit_hicache_staged_module(element_size=row_bytes, unroll=4, block_quota=2)
        changed = compiled[row_bytes]
        for pages in (753, 4096, 16384):
            if time.monotonic() + 5 > deadline:
                lines.append('BUDGET_STOP before shape')
                break
            dim = row_bytes // dtype.itemsize
            gen = torch.Generator(device='cuda').manual_seed(9281 + pages + layers)
            k = torch.randint(0, 256, (layers, pages + 16, row_bytes), device='cuda', dtype=torch.uint8, generator=gen).view(dtype)
            v = k.view(torch.uint8).bitwise_xor(57).view(dtype)
            kp = torch.tensor([x.data_ptr() for x in k], device='cuda', dtype=torch.uint64)
            vp = torch.tensor([x.data_ptr() for x in v], device='cuda', dtype=torch.uint64)
            src = torch.arange(pages, device='cuda', dtype=torch.int64)
            dst = torch.arange(pages, dtype=torch.int64) + 8
            sk = torch.empty((pages, layers, dim), device='cuda', dtype=dtype)
            sv = torch.empty_like(sk)
            hk = torch.empty((pages + 16, layers, dim), dtype=dtype, pin_memory=True)
            hv = torch.empty_like(hk, pin_memory=True)
            results = {}
            for name, fn in [('stock', original.launch_all_lf_pf_staged), ('coalesced', changed.launch)]:
                fn(hk, hv, dst, sk, sv, src, kp, vp, 1)
                torch.cuda.synchronize()
                for got, source in [(hk, k), (hv, v)]:
                    expected = source[:, :pages].view(torch.uint8).permute(1, 0, 2)
                    assert torch.equal(got[8:8+pages].view(torch.uint8), expected.cpu()), (name, layers, pages)
                enqueue, complete = [], []
                for _ in range(20):
                    torch.cuda.synchronize()
                    t0 = time.perf_counter()
                    fn(hk, hv, dst, sk, sv, src, kp, vp, 1)
                    t1 = time.perf_counter()
                    torch.cuda.synchronize()
                    enqueue.append((t1-t0)*1e6)
                    complete.append((time.perf_counter()-t0)*1e6)
                results[name] = (statistics.median(enqueue), statistics.median(complete))
            graph_ok = None
            if pages == 753:
                graph = torch.cuda.CUDAGraph()
                with torch.cuda.graph(graph):
                    changed.launch(hk, hv, dst, sk, sv, src, kp, vp, 1)
                k.view(torch.uint8).bitwise_xor_(3)
                graph.replay(); torch.cuda.synchronize()
                graph_ok = torch.equal(hk[8:8+pages].view(torch.uint8), k[:, :pages].view(torch.uint8).permute(1, 0, 2).cpu())
                assert graph_ok, 'fresh graph bytes'
                graph.reset()
            lines.append(f'KV_COPY bytes={row_bytes} L={layers} P={pages} exact=1 graph={"skip" if graph_ok is None else "pass"} planned_copies={pages*2}/2 '
                         f'stock_enqueue_us={results["stock"][0]:.3g} new_enqueue_us={results["coalesced"][0]:.3g} '
                         f'stock_complete_us={results["stock"][1]:.3g} new_complete_us={results["coalesced"][1]:.3g}')
    directory.cleanup()
    return lines
